sourcesContent:
.logo {
  width: 10rem;
}

.penn-logo {
  width: 6.5rem;
}
.mtl-logo {
  width: 13rem;
}
.rdam-logo {
  width: 8rem;
}
h3 {
  font-family: SkModernistRegular;
}
.download-text {
  height: 1.3rem;
  width: 8rem;
  bottom: 0;
  text-align: center;
  top: 0;
  margin: auto;
  z-index: 2;
  position: absolute;
  left: 0;
  right: 0;
  color: black;
}
.share-container {
  border:1px solid #e8fcd4;
  border-radius:40px;
  /* background:#e8fcd4; */

}
.share-text {
    color: #e8fcd4;
}
.download-text-light {
  color: #201f1d;
}
.download-text {
  pointer-events: none;
}

.download-btn {
  transition: transform ease 100ms, fill 0.15s ease-in-out;
  transform-origin: center center;
}
.download-btn:hover {
  transform-origin: center center;
  transform: scale(0.9);
  cursor: pointer;

  fill: #e8fcd4 !important;
}

/* circle:last-child:hover {
  fill: #d9d9d9 !important;
} */

.title {
  font-family: SkModernistRegular;
  line-height: 2rem;
  font-size: 1.8rem;
  color: #e8fcd4;
}
@media (min-width: 768px) {
  .title {
    font-size: 2.8rem;
    line-height: 2.8rem;
  }
}

.btn-container {
  height: 34rem;
}

.ripple {
  bottom: 0;
  top: 0;
  margin: auto;
  position: absolute;

  left: 0;
  right: 0;
}
.download {
  height: auto;
  min-height: 100vh;
  background: #201f1d;
  overflow: hidden;
}

circle {
  fill: #747474;
  opacity: 0.3;
}
svg > circle:last-child {
  fill: #e8fcd4 !important;
  opacity: 1;
}
svg g {
  transform: translate(50%, 50%);
}
#rp1 {
  animation: ripple1 2s linear infinite;
  position: absolute;
  bottom: 0;
}
@keyframes ripple1 {
  0% {
    transform: scale(5.5);
    opacity: 0.3;
  }
  100% {
    transform: scale(8.5);
    opacity: 0;
  }
}
h3 {
  color: #e8fcd4;
}

#rp2 {
  animation: ripple2 2s linear infinite;
}
@keyframes ripple2 {
  0% {
    transform: scale(3.5);
  }
  100% {
    transform: scale(5.5);
  }
}
#rp3 {
  animation: ripple3 2s linear infinite;
}
@keyframes ripple3 {
  0% {
    transform: scale(1.5);
  }
  100% {
    transform: scale(3.5);
  }
}
#rp4 {
  animation: ripple4 2s linear infinite;
}
@keyframes ripple4 {
  0% {
    transform: scale(0.5);
  }
  100% {
    transform: scale(1.5);
  }
}
